"use client";

import { motion } from "framer-motion";
import { ArrowLeft, Rocket, Target, Zap, Projector, Briefcase, ExternalLink } from "lucide-react";
import Link from "next/link";
import { projects } from "@/data/projects";

export default function ProductsPage() {
  return (
    <main className="min-h-screen pt-32 pb-20 px-8 md:px-16 bg-background relative overflow-hidden">
      <div className="max-w-7xl mx-auto space-y-12">
        <Link href="/" className="inline-flex items-center gap-2 text-[10px] font-black uppercase text-primary hover:gap-3 transition-all">
          <ArrowLeft className="w-3 h-3" /> Back Home
        </Link>
        <h1 className="text-7xl font-black text-white tracking-tighter font-outfit uppercase">
          Project <span className="text-primary italic">Portfolio.</span>
        </h1>
        <p className="text-xl text-white/40 font-bold max-w-2xl leading-relaxed font-outfit">
          Engineering excellence at scale. Explore our high-performance deployments across multiple industries and tech stacks.
        </p>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
           {projects.map((p, i) => (
             <div key={i} className="p-8 bg-white/[0.02] border border-white/5 rounded-[2.5rem] hover:bg-white/[0.05] hover:border-primary/20 transition-all group backdrop-blur-3xl shine-effect">
                <div className="flex justify-between items-start mb-6">
                  <p className="text-[9px] font-black text-primary uppercase tracking-[0.3em]">{p.category}</p>
                   <div className="flex gap-1.5">
                    {p.tags.slice(0, 2).map(tag => (
                      <span key={tag} className="px-1.5 py-0.5 bg-white/5 border border-white/10 rounded text-[6px] font-black uppercase tracking-widest text-white/40">{tag}</span>
                    ))}
                  </div>
                </div>
                <h3 className="text-xl font-black text-white mb-3 font-outfit uppercase tracking-tighter group-hover:text-primary transition-colors">{p.title}</h3>
                <p className="text-white/30 text-[10px] font-bold leading-relaxed mb-8 h-8 overflow-hidden line-clamp-2">{p.description}</p>
                <div className="flex items-center justify-between">
                  <Link href={`/projects/${p.slug}`} className="text-[9px] font-black uppercase text-white group-hover:text-primary transition-colors flex items-center gap-2">
                    Case Study <Briefcase className="w-3 h-3" />
                  </Link>
                  {p.demoUrl && (
                    <Link href={p.demoUrl} target="_blank" className="text-[9px] font-black uppercase text-white/10 hover:text-white transition-colors flex items-center gap-2">
                      Live <ExternalLink className="w-3 h-3" />
                    </Link>
                  )}
                </div>
             </div>
           ))}
        </div>
      </div>
    </main>
  );
}
